      const said = await cdp.evaluate(`
        const all = [...document.querySelectorAll('[data-cy=assistant-message]')]
        return all.at(-1)?.textContent?.replace(/\\s+/g, ' ').trim().slice(0, 120) ?? null`)
      // 🔴 **704 · did the CLI RECEIVE `/clear` as a command?** — step 62's question; since `708`
      // (`R42`) the answer should be yes, and a wrapped one is the ruling regressing.
      const received = await howTheCliReceived(cdp, '/clear')
      if ('wrapped' in received) {
        throw new Error(
          `the CLI never received /clear as a command — the app sent it inside other text ` +
            `(607's authorship preamble — R42, 708, says a person's command goes as typed), so ` +
            `nothing was cleared and the model answered the ` +
            `words: ${JSON.stringify(received.wrapped.slice(0, 160))} · it said: "${said ?? '(nothing)'}"`,
        )
      }
      // ⛔ **721 · the CLI's own frame, not the app's event, is the premise.** Since R75 the app raises
